impl CapabilityClient for PasskeyClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            begin_authentication: dependencies.one::<PasskeyBeginAuthentication>()?,
            begin_registration: dependencies.one::<PasskeyBeginRegistration>()?,
            finish_authentication: dependencies.one::<PasskeyFinishAuthentication>()?,
            finish_registration: dependencies.one::<PasskeyFinishRegistration>()?,
            list_passkeys: dependencies.one::<PasskeyListPasskeys>()?,
            revoke_passkey: dependencies.one::<PasskeyRevokePasskey>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for PasskeyClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    begin_authentication: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PasskeyBeginAuthentication>()?,
                    begin_registration: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PasskeyBeginRegistration>()?,
                    finish_authentication: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PasskeyFinishAuthentication>()?,
                    finish_registration: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PasskeyFinishRegistration>()?,
                    list_passkeys: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PasskeyListPasskeys>()?,
                    revoke_passkey: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<PasskeyRevokePasskey>()?,
                    },
                ))
            })
            .collect()
    }
}

